SELECT AVG(rating) AS avg_rating, COUNT(*) AS review_count
FROM reviews
WHERE parent_asin = 'B0C46SPKJ9';

SELECT COUNT(*) AS review_count, ROUND(AVG(rating), 2) AS avg_rating
FROM reviews
WHERE parent_asin = 'B0C46SPKJ9';

SELECT AVG(r.rating) AS avg_rating, COUNT(*) AS review_count
FROM reviews r
WHERE r.parent_asin = 'B0C46SPKJ9';
